data.pageSchema:
{
  "renderer": "page",
  "initData": {
    "pdps": "2"
  },
  "body": [
    {
      "renderer": "layout",
      "body": [
        {
          "renderer": "form",
          "controls": [
            {
              "renderer": "radio",
              "name": "pdps",
              "label": "新建广告",
              "options": [
                {
                  "text": "开机广告",
                  "value": "1"
                },
                {
                  "text": "发现页广告",
                  "value": "2"
                },
                {
                  "text": "主页类广告",
                  "value": "3",
                  "disabledOn": ""
                }
              ],
              "classname": "flex a-s d-c",
              "target": "SceneCards"
            }
          ],
          "labelPosition": "top",
          "classname": "scene_aside__form"
        },
        {
          "renderer": "divider",
          "direction": "vertical",
          "classname": "scene_aside__divider"
        },
        {
          "renderer": "cards",
          "initApi": {
            "url": "/api/mock/getSceneItem",
            "method": "get",
            "params": {
              "pdps": "${pdps}"
            }
          },
          "shadow": "hover",
          "span": 4,
          "name": "SceneCards",
          "gutter": 10,
          "events": {
            "click": {
              "renderer": "action",
              "text": "<%=data.text%>",
              "isText": true,
              "plain": true,
              "body": {},
              "tipContent": "${description}",
              "actionType": "url",
              "url": "/superfans/discoveryView",
              "params": {
                "id": "${id}"
              },
              "type": "info",
              "size": "small"
            }
          },
          "footer": [
            {
              "renderer": "action",
              "text": "<%=data.text%>",
              "isText": true,
              "plain": true,
              "body": {},
              "tipContent": "${description}",
              "actionType": "url",
              "url": "/superfans/discoveryView",
              "params": {
                "id": "${id}"
              },
              "type": "info",
              "size": "small"
            },
            {
              "renderer": "action",
              "text": " ",
              "category": "icon",
              "icon": "QuestionFilled",
              "popupType": "tip",
              "tipContent": "${description}",
              "body": {},
              "size": 12,
              "static": true
            }
          ],
          "body": [
            {
              "renderer": "mapping",
              "distributes": [
                "type"
              ],
              "body": [],
              "optionConfig": {
                "text": "",
                "value": ""
              },
              "map": {
                "1": "创意",
                "2": "wax",
                "3": "标准"
              },
              "value": "type",
              "status": "type"
            },
            {
              "renderer": "image",
              "src": "${previewImg}",
              "previews": []
            }
          ],
          "hasPageInfo": false,
          "classname": "zoom_move_2"
        }
      ],
      "direction": "horizontal"
    }
  ],
  "innerStyle": ".scene_aside__form {\n  .el-radio__input {\n    display: none;\n  }\n  .el-radio__label {\n    font-weight: 400;\n  }\n  .i-form__field__label {\n    font-size: 18px;\n    font-weight: 500;\n  }\n}\n.scene_aside__divider {\n  height: 100%;\n}\n.i-crud__container {\n  width: 100%;\n  overflow-y: auto;\n  .i-component__fragment+.i-component__fragment {\n    margin-left: 5px;\n  }\n  .i-card__body {\n    padding: 0;\n  }\n  .i-card__footer {\n    padding: 8px;\n  }\n}\n.i-mapping__container {\n  position: absolute;\n  top: 3px;\n  right: -28px;\n  width: 100px;\n  height: 33px;\n  padding: 6px;\n  text-align: center;\n  background: var(--el-color-success);\n  color: var(--el-color-white);\n  transform: rotateZ(45deg);\n  box-shadow: var(--el-box-shadow-dark);\n  z-index: 10;\n  &.primary {\n    background: var(--el-color-primary);\n  }\n  &.success {\n    background: var(--el-color-success);\n  }\n}"
}
